20	template <typename TileData, typename GlobalData>
21	PTO_INTERNAL void TLoadInstrGm2ub(
22	    __ubuf__ typename TileData::DType* dst, typename GlobalData::DType* src, uint16_t nBurst, uint32_t lenBurst,
23	    uint32_t gmGap, uint32_t ubGap, uint32_t ubPad)
24	{
25	    if constexpr (sizeof(typename TileData::DType) == 1) {
26	        copy_gm_to_ubuf_align_b8(dst, src, 0, nBurst, lenBurst, 0, ubPad, gmGap, ubGap);
27	    } else if constexpr (sizeof(typename TileData::DType) == 2) {
28	        copy_gm_to_ubuf_align_b16(dst, src, 0, nBurst, lenBurst, 0, ubPad, gmGap, ubGap);
29	    } else if constexpr (sizeof(typename TileData::DType) == 4) {
30	        copy_gm_to_ubuf_align_b32(dst, src, 0, nBurst, lenBurst, 0, ubPad, gmGap, ubGap);
31	    } else if constexpr (sizeof(typename TileData::DType) == 8) {
32	        copy_gm_to_ubuf_align_b32(dst, src, 0, nBurst, lenBurst, 0, ubPad * 2, gmGap, ubGap);
33	    }
34	}
35	
36	#include <pto/common/utils.hpp>
37	
38	template <typename TileData, typename GlobalData>
39	PTO_INTERNAL void TLoadInstrGm2L1(
40	    __cbuf__ typename TileData::DType* dst, typename GlobalData::DType* src, uint16_t nBurst, uint16_t lenBurst,
41	    uint16_t gmGap, uint16_t l1Gap)
42	{
43	    pto_copy_gm_to_cbuf(dst, src, (uint8_t)0, nBurst, lenBurst, gmGap, l1Gap);
44	}
45	
46	template <typename TileData, typename GlobalData>
47	__tf__ PTO_INTERNAL void TLoadNDC1HWC0(
48	    typename TileData::TileDType __out__ dst, typename GlobalData::DType __in__* src, int srcN, int srcD, int srcC1,
49	    int srcH, int srcW, int gStride0, int gStride1, int gStride2, int gStride3, int gStride4, int dstN, int dstD,
50	    int dstC1, int dstH, int dstW)
51	{
52	    __cbuf__ typename TileData::DType* dstAddr = (__cbuf__ typename TileData::DType*)__cce_get_tile_ptr(dst);
53	    typename GlobalData::DType* srcAddr = src;
54	
55	    constexpr uint32_t c0ElemCount = C0_SIZE_BYTE / sizeof(typename TileData::DType);
56	    typename GlobalData::DType* srcAddrP = srcAddr;
57	    __cbuf__ typename TileData::DType* dstAddrP = dstAddr;
58	    constexpr uint32_t maxSupportBurst = 4095;
59	    uint32_t gmGap = ((gStride2 - dstH * dstW * c0ElemCount) * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
60	
61	    if ((gStride3 == dstW * c0ElemCount || dstH == 1) && gmGap <= UINT16_MAX && dstC1 <= maxSupportBurst &&
62	        dstH * dstW <= UINT16_MAX) {
63	        uint16_t nBurst = dstC1;
64	        uint16_t srcGap = gmGap;
65	        uint16_t lenBurst = dstH * dstW;
66	        for (uint32_t i = 0; i < dstN; i++) {
67	            int64_t srcAddr1 = i * gStride0;
68	            int64_t dstAddr1 = i * dstD * dstH * dstW * dstC1 * c0ElemCount;
69	            for (uint32_t j = 0; j < dstD; j++) {
70	                srcAddrP = srcAddr + srcAddr1 + j * gStride1;
71	                dstAddrP = dstAddr + dstAddr1 + j * dstH * dstW * dstC1 * c0ElemCount;
72	                TLoadInstrGm2L1<TileData, GlobalData>(dstAddrP, srcAddrP, nBurst, lenBurst, srcGap, 0);
73	            }
74	        }
75	    } else {
76	        PTO_ASSERT(dstH <= maxSupportBurst, "Fix: max support dstH is 4095!");
77	        PTO_ASSERT(dstW <= UINT16_MAX, "Fix: max support dstW is UINT16_MAX!");
78	
79	        uint16_t nBurst = dstH;
80	        uint16_t lenBurst = dstW;
81	        uint16_t srcGap = ((gStride3 - srcW * c0ElemCount) * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
82	        uint16_t l1Gap = 0;
83	        for (uint32_t i = 0; i < dstN; i++) {
84	            int64_t srcAddr1 = i * gStride0;
85	            int64_t dstAddr1 = i * dstD * dstH * dstW * dstC1 * c0ElemCount;
86	            for (uint32_t j = 0; j < dstD; j++) {
87	                int64_t srcAddr2 = j * gStride1;
88	                int64_t dstAddr2 = j * dstH * dstW * dstC1 * c0ElemCount;
89	                for (uint32_t k = 0; k < dstC1; k++) {
90	                    srcAddrP = srcAddr + srcAddr1 + srcAddr2 + k * gStride2;
91	                    dstAddrP = dstAddr + dstAddr1 + dstAddr2 + k * dstH * dstW * c0ElemCount;
92	                    TLoadInstrGm2L1<TileData, GlobalData>(dstAddrP, srcAddrP, nBurst, lenBurst, srcGap, l1Gap);
93	                }
94	            }
95	        }
96	    }
97	}
