295	template <typename TileData, typename GlobalData>
296	PTO_INTERNAL void CheckConvTileData(TileData& dst, GlobalData& src)
297	{
298	    static_assert(
299	        std::is_same_v<typename TileData::DType, int8_t> || std::is_same_v<typename TileData::DType, uint8_t> ||
300	            std::is_same_v<typename TileData::DType, int16_t> || std::is_same_v<typename TileData::DType, uint16_t> ||
301	            std::is_same_v<typename TileData::DType, int32_t> || std::is_same_v<typename TileData::DType, uint32_t> ||
302	            std::is_same_v<typename TileData::DType, half> || std::is_same_v<typename TileData::DType, bfloat16_t> ||
303	            std::is_same_v<typename TileData::DType, float>,
304	        "Fix: Data type must be int8_t/uint8_t/int16_t/uint16_t/int32_t/uint32_t/half/bfloat16_t/float!");
305	    static_assert(TileData::Loc == pto::TileType::Mat, "Fix: Dst TileType must be Mat!");
306	    static_assert(
307	        sizeof(typename TileData::DType) == sizeof(typename GlobalData::DType),
308	        "Fix: Source dtype must be same with dst dtype!");
309	
310	    constexpr bool isSameLayout =
311	        (GlobalData::layout == pto::Layout::NC1HWC0 && TileData::layout == pto::Layout::NC1HWC0) ||
312	        (GlobalData::layout == pto::Layout::FRACTAL_Z && TileData::layout == pto::Layout::FRACTAL_Z) ||
313	        (GlobalData::layout == pto::Layout::FRACTAL_Z_3D && TileData::layout == pto::Layout::FRACTAL_Z_3D) ||
314	        (GlobalData::layout == pto::Layout::NDC1HWC0 && TileData::layout == pto::Layout::NDC1HWC0);
315	    static_assert(
316	        isSameLayout == true, "Fix: Src Dst layout must be NC1HWC0 or FRACTAL_Z or FRACTAL_Z_3D or NDC1HWC0!");
317	}
