51	    const size_t validRow = src.GetValidRow();
52	    const size_t validCol = src.GetValidCol();
53	
54	    const std::vector<int64_t> shapes = {
55	        dst.GetShape(GlobalTensorDim::DIM_0), dst.GetShape(GlobalTensorDim::DIM_1),
56	        dst.GetShape(GlobalTensorDim::DIM_2), dst.GetShape(GlobalTensorDim::DIM_3),
