31	template <typename GlobalData, typename TileData>
32	PTO_INTERNAL void TStoreUb2gmDn2dn(
33	    typename GlobalData::DType* dstAddr, __ubuf__ typename TileData::DType* srcAddr, int gShape0, int gShape1,
34	    int gShape2, int gShape3, int gShape4, int gStride0, int gStride1, int gStride2, int gStride3, int gStride4,
35	    int validRow, int validCol)
36	{
37	    PTO_ASSERT(validRow == gShape3, "The validCol of TileData must be equal to the 4th dim(Shape3) of DN shape!");
38	    PTO_ASSERT(
39	        validCol == gShape0 * gShape1 * gShape2 * gShape4,
40	        "The validRow of TileData must be equal to (Shape0 * Shape1 * Shape2 * Shape4) of DN shape!");
41	    PTO_ASSERT(gShape4 < 4096, "The gshape4 (which equals nBurst) must be less than 4096");
42	    uint16_t nBurst = gShape4;
43	    uint32_t lenBurst = validRow * sizeof(typename TileData::DType);
44	    uint32_t gmGap = (gStride4 - gShape3) * sizeof(typename TileData::DType);
45	    uint32_t ubGap = ((TileData::Rows - gShape3) * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
46	    typename GlobalData::DType* dstGlobalAddr = dstAddr;
47	    __ubuf__ typename TileData::DType* srcTileAddr = srcAddr;
48	    int64_t srcStride2 = TileData::Rows * gShape4;
49	    int64_t srcStride1 = gShape2 * srcStride2;
50	    int64_t srcStride0 = gShape1 * srcStride1;
51	
52	    for (uint32_t i = 0; i < gShape0; i++) {
53	        int64_t srcAddr0 = i * srcStride0;
54	        int64_t dstAddr0 = i * gStride0;
55	        for (uint32_t j = 0; j < gShape1; j++) {
56	            int64_t srcAddr1 = j * srcStride1;
57	            int64_t dstAddr1 = j * gStride1;
58	            for (uint32_t k = 0; k < gShape2; k++) {
59	                dstGlobalAddr = dstAddr + dstAddr0 + dstAddr1 + k * gStride2;
60	                srcTileAddr = srcAddr + srcAddr0 + srcAddr1 + k * srcStride2;
61	                TStoreUb2gmInstr<GlobalData, TileData>(dstGlobalAddr, srcTileAddr, nBurst, lenBurst, gmGap, ubGap);
62	            }
63	        }
64	    }
65	}
