98	template <
99	    typename GlobalData, typename TileData, QuantMode_t quantizationMode = QuantMode_t::NoQuant,
100	    ReluPreMode reluPreMode = ReluPreMode::NoRelu, STPhase Phase = STPhase::Unspecified>
101	PTO_INTERNAL void TStoreAccNz2nz(
102	    typename GlobalData::DType* dstAddr, __cc__ typename TileData::DType* srcAddr, int gShape0, int gShape1,
103	    int gShape2, int gShape3, int gShape4, int gStride0, int gStride1, int gStride2, int gStride3, int gStride4,
104	    int validRow, int validCol)
105	{
106	    PTO_ASSERT(validRow == gShape2 * gShape3, "The validRow of TileData must be equal to Shape2 * Shape3 of NZ shape!");
107	    PTO_ASSERT(
108	        validCol == gShape0 * gShape1 * gShape4,
109	        "The validCol of TileData must be equal to Shape0 * Shape1 * Shape4 of NZ shape!");
110	    PTO_ASSERT(
111	        validRow >= 1 && validRow <= 65535 && validCol % 16 == 0,
112	        "When GlobalData is NZ format, the range of validRow is [1, 65535] and validCol must be an integer multiple of "
113	        "16.");
114	
115	    static_assert(
116	        GlobalData::staticShape[3] == FRACTAL_NZ_ROW,
117	        "When GlobalData is NZ format, the second-to-last dimension shall be 16.");
118	    static_assert(
119	        (std::is_same_v<typename GlobalData::DType, __gm__ float> &&
120	         (GlobalData::staticShape[4] == 8 || GlobalData::staticShape[4] == 16)) ||
121	            (std::is_same_v<typename GlobalData::DType, __gm__ int32_t> && GlobalData::staticShape[4] == 16) ||
122	            (GlobalData::staticShape[4] == BLOCK_BYTE_SIZE / sizeof(typename GlobalData::DType)),
123	        "When GlobalData is in NZ format: if DstType is float, the last dimension must be either 8 or 16, "
124	        "and the dimension value is 8 if and only if Channel Split is enabled; if DstType is int32_t, the "
125	        "last dimension must be exactly 16. In addition, the last dimension must be static and satisfy 32 / "
126	        "sizeof(DstType).");
127	
128	    uint16_t mSize = validRow;
129	    uint16_t nSize = validCol;
130	
131	    uint32_t c0Size = sizeof(typename GlobalData::DType) * gShape4;
132	    uint16_t srcStride = TileData::Rows;
133	    if constexpr (CompactMode::Normal == TileData::Compact) {
134	        srcStride = (FRACTAL_NZ_ROW + validRow - 1) / FRACTAL_NZ_ROW * FRACTAL_NZ_ROW;
135	    }
136	    uint32_t dstStride = gShape2 * gShape3 * c0Size >> SHIFT_BLOCK_BYTE;
137	
138	    constexpr uint8_t unitFlagCtrl = static_cast<uint8_t>(Phase);
139	    uint8_t channelSplitEn = 0;
140	    if (std::is_same_v<typename TileData::DType, float> && std::is_same_v<typename GlobalData::DType, __gm__ float>) {
141	        if (gShape4 == 8) {
142	            channelSplitEn = 1;
143	        }
144	    }
145	
146	    uint64_t xmReg =
147	
148	        (static_cast<uint64_t>(nSize & 0xfff) << 4) |          // Xm[15:4] nSize
149	        (static_cast<uint64_t>(mSize & 0xffff) << 16) |        // Xm[31:16] mSize
150	        (static_cast<uint64_t>(dstStride & 0xffffffff) << 32); // Xm[63:32] destination stride between the start addr
151	
152	    uint64_t xtReg = srcStride | // Xt[15:0] the source stride between the start addr
153	                     (static_cast<uint64_t>(unitFlagCtrl & 0x3) << 32) |      // Xt[33:32] unit flag control bit
154	                     (static_cast<uint64_t>(quantizationMode & 0x1f) << 34) | // Xt[38:34] pre-stage quantization mode
155	                     ((static_cast<uint64_t>(reluPreMode) & 0x7) << 39) |     //  Xt[41:39] relu pre mode
156	                     (static_cast<uint64_t>(channelSplitEn & 0x1) << 42);     // Xt[42] channel split control bit
157	
158	    copy_matrix_cc_to_gm(dstAddr, srcAddr, xmReg, xtReg);
159	}
