191	template <typename TileData, typename GlobalData, bool isQuant>
192	PTO_INTERNAL void CheckAcc2gm(GlobalData& dst, TileData& src)
193	{
194	    static_assert(
195	        (GlobalData::layout == Layout::ND || GlobalData::layout == Layout::NZ ||
196	         GlobalData::layout == Layout::NC1HWC0 || GlobalData::layout == Layout::NDC1HWC0),
197	        "The output data layout must be ND, NZ, NC1HWC0 or NDC1HWC0.");
198	    static_assert(
199	        std::is_same_v<typename TileData::DType, int32_t> || std::is_same_v<typename TileData::DType, float>,
200	        "The input data type must be restricted to int32_t/float!");
201	    if constexpr (!isQuant) {
202	        static_assert(
203	            std::is_same_v<typename GlobalData::DType, __gm__ int32_t> ||
204	                std::is_same_v<typename GlobalData::DType, __gm__ float> ||
205	                std::is_same_v<typename GlobalData::DType, __gm__ half> ||
206	                std::is_same_v<typename GlobalData::DType, __gm__ bfloat16_t>,
207	            "The output data type must be restricted to int32_t/float/half/bfloat16_t!");
208	    } else if constexpr (isQuant) {
209	        if constexpr (std::is_same_v<typename TileData::DType, float>) {
210	            static_assert(
211	                std::is_same<typename GlobalData::DType, __gm__ int8_t>::value ||
212	                    std::is_same<typename GlobalData::DType, __gm__ uint8_t>::value,
213	                "The output data type must be restricted to int8_t/uint8_t when the source data type is float.");
214	        } else if constexpr (std::is_same_v<typename TileData::DType, int32_t>) {
215	            static_assert(
216	                std::is_same<typename GlobalData::DType, __gm__ int8_t>::value ||
217	                    std::is_same<typename GlobalData::DType, __gm__ uint8_t>::value ||
218	                    std::is_same<typename GlobalData::DType, __gm__ half>::value,
219	                "The output data type must be restricted to half/int8_t/uint8_t when the source data type is int32_t.");
220	        }
221	    }
222	    static_assert(TileData::Cols >= 1 && TileData::Cols <= 4095, "The range of Cols is [1, 4095].");
223	    static_assert(
224	        (GlobalData::layout == Layout::ND && TileData::Rows >= 1 && TileData::Rows <= 8192) ||
225	            ((GlobalData::layout == Layout::NZ || GlobalData::layout == Layout::NC1HWC0 ||
226	              GlobalData::layout == Layout::NDC1HWC0) &&
227	             TileData::Rows >= 1 && TileData::Rows <= 65535 && TileData::Cols % 16 == 0),
228	        "When GlobalData is ND format, the range of Rows is [1, 8192]."
229	        "When GlobalData is NZ or NC1HWC0 or NDC1HWC0 format, the range of Rows is [1, 65535] and Cols "
230	        "must be an integer multiple of 16.");
231	    PTO_ASSERT(src.GetValidCol() >= 1 && src.GetValidCol() <= 4095, "The range of validCol is [1, 4095].");
232	    PTO_ASSERT(
233	        dst.GetShape(GlobalTensorDim::DIM_0) > 0 && dst.GetShape(GlobalTensorDim::DIM_1) > 0 &&
234	            dst.GetShape(GlobalTensorDim::DIM_2) > 0 && dst.GetShape(GlobalTensorDim::DIM_3) > 0 &&
235	            dst.GetShape(GlobalTensorDim::DIM_4) > 0 && src.GetValidRow() > 0 && src.GetValidCol() > 0,
236	        "The shape of src and dst must be greater than 0!");
237	}
238	
239	template <
240	    typename TileData, typename GlobalData, AtomicType currentAtomicType = AtomicType::AtomicNone,
241	    STPhase Phase = STPhase::Unspecified>
242	PTO_INTERNAL void TSTORE_IMPL(GlobalData& dst, TileData& src)
243	{
244	    static_assert(
245	        TileData::Loc == TileType::Vec || TileData::Loc == TileType::Acc || TileData::Loc == TileType::Mat,
246	        "Source TileType only support Vec/Acc/Mat!");
247	    PTO_ASSERT(
248	        dst.GetShape(GlobalTensorDim::DIM_0) > 0 && dst.GetShape(GlobalTensorDim::DIM_1) > 0 &&
249	            dst.GetShape(GlobalTensorDim::DIM_2) > 0 && dst.GetShape(GlobalTensorDim::DIM_3) > 0 &&
250	            dst.GetShape(GlobalTensorDim::DIM_4) > 0 && src.GetValidRow() > 0 && src.GetValidCol() > 0,
251	        "The shape of src and dst must be greater than 0!");
252	    if constexpr (currentAtomicType == AtomicType::AtomicAdd) {
253	        SetAtomicAdd<typename GlobalData::DType>();
254	    }
255	    if constexpr (TileData::Loc == TileType::Vec) {
256	        CheckStaticForVecAndMat<TileData, GlobalData>();
257	        TStore<GlobalData, TileData>(
258	            dst.data(), src.data(), dst.GetShape(GlobalTensorDim::DIM_0), dst.GetShape(GlobalTensorDim::DIM_1),
259	            dst.GetShape(GlobalTensorDim::DIM_2), dst.GetShape(GlobalTensorDim::DIM_3),
260	            dst.GetShape(GlobalTensorDim::DIM_4), dst.GetStride(GlobalTensorDim::DIM_0),
261	            dst.GetStride(GlobalTensorDim::DIM_1), dst.GetStride(GlobalTensorDim::DIM_2),
262	            dst.GetStride(GlobalTensorDim::DIM_3), dst.GetStride(GlobalTensorDim::DIM_4), src.GetValidRow(),
263	            src.GetValidCol());
264	    } else if constexpr (TileData::Loc == TileType::Acc) {
265	        CheckAcc2gm<TileData, GlobalData, false>(dst, src);
266	        constexpr QuantMode_t quantMode = GetCastPreQuantMode<typename TileData::DType, typename GlobalData::DType>();
267	        TStoreAcc<GlobalData, TileData, quantMode, ReluPreMode::NoRelu, Phase>(
268	            dst.data(), src.data(), dst.GetShape(GlobalTensorDim::DIM_0), dst.GetShape(GlobalTensorDim::DIM_1),
269	            dst.GetShape(GlobalTensorDim::DIM_2), dst.GetShape(GlobalTensorDim::DIM_3),
270	            dst.GetShape(GlobalTensorDim::DIM_4), dst.GetStride(GlobalTensorDim::DIM_0),
271	            dst.GetStride(GlobalTensorDim::DIM_1), dst.GetStride(GlobalTensorDim::DIM_2),
272	            dst.GetStride(GlobalTensorDim::DIM_3), dst.GetStride(GlobalTensorDim::DIM_4), src.GetValidRow(),
273	            src.GetValidCol());
274	    } else if constexpr (TileData::Loc == TileType::Mat) {
275	        CheckStaticForVecAndMat<TileData, GlobalData>();
276	        TStoreMat<GlobalData, TileData>(
277	            dst.data(), src.data(), dst.GetShape(GlobalTensorDim::DIM_0), dst.GetShape(GlobalTensorDim::DIM_1),
278	            dst.GetShape(GlobalTensorDim::DIM_2), dst.GetShape(GlobalTensorDim::DIM_3),
279	            dst.GetShape(GlobalTensorDim::DIM_4), dst.GetStride(GlobalTensorDim::DIM_0),
280	            dst.GetStride(GlobalTensorDim::DIM_1), dst.GetStride(GlobalTensorDim::DIM_2),
281	            dst.GetStride(GlobalTensorDim::DIM_3), dst.GetStride(GlobalTensorDim::DIM_4), src.GetValidRow(),
282	            src.GetValidCol());
283	    }
284	    if constexpr (currentAtomicType == AtomicType::AtomicAdd) {
285	        SetAtomicNone();
286	    }
287	}
